import{_ as t,l as i,o as e,c as r,v as s,p as d,x as o,d as l,i as n,S as f}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"fsck","description":"","frontmatter":{"title":"fsck","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fsck.md","filePath":"cs/fsck.md","lastUpdated":1789023840000}'),p={name:"cs/fsck.md"};function E(k,a,h,u,m,_){const c=i("Mermaid");return e(),r("div",null,[a[1]||(a[1]=s('<h1 id="fsck" tabindex="-1">fsck <a class="header-anchor" href="#fsck" aria-label="Permalink to &quot;fsck&quot;">​</a></h1><div class="epigraph"><p>fsck 从超级块走进位图、inode 与目录，把「结构不变量」从盘上核对一遍；能修则修，不能则标坏。</p><footer>—— 据 McKusick and Kowalski 对 fsck 的论述；Arpaci-Dusseau, <em>OSTEP</em> 对一致性检查的整理</footer></div><p><a href="/cs/soft-updates">上一课</a>把泄漏交给后台回收。<a href="/cs/ext4-journal">日志</a> 把重放当成主恢复路径。无论哪条路，仍需要一个<strong>离线或只读在线的检查器</strong>，把不变量写成程序。缺口是 fsck 扫什么，而不是再发明 inode。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不变量包括：每个已分配块恰被一个 inode 指向（或空闲）；目录项的 inode 已分配且类型匹配；<code>.</code> / <code>..</code> 成树；链接计数等于目录项数。无日志的 <a href="/cs/fat-filesystem">FAT</a> / 老 ext2 崩溃后必须全量跑。有日志时，正常 umount 只设 clean 标志，fsck 跳过；脏挂载先重放再抽查。缺口：阶段（超级块、柱面组/块组、inode、连通性、引用计数）以及「修」与「只报」的差别。</p><p><span class="marginnote">e2fsck、fsck.f2fs、btrfs check 对象不同，阶段同构。不要在生产上对 COW 池用「按 FAT 思路重建簇链」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读超级块与备份，确认块组描述符。扫 inode 表，统计块引用，对照位图。走目录树，发现悬空 inode（已分配无目录项）放 <code>lost+found</code>。修正链接计数。FAT 的 scandisk 类工具扫簇链环与交叉。与 scrub 对照：<a href="/cs/fs-checksum-scrub">scrub</a> 信树结构去读数据校验；fsck 先信或重建结构。</p>',8)),(e(),d(f,null,{default:o(()=>[n(c,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SB%5B%22%E8%B6%85%E7%BA%A7%E5%9D%97%22%5D%20--%3E%20BG%5B%22%E7%BB%84%E6%8F%8F%E8%BF%B0%E7%AC%A6%E4%B8%8E%E4%BD%8D%E5%9B%BE%22%5D%0A%20%20BG%20--%3E%20INO%5B%22inode%20%E4%B8%8E%E5%9D%97%E5%BC%95%E7%94%A8%22%5D%0A%20%20INO%20--%3E%20DIR%5B%22%E7%9B%AE%E5%BD%95%E8%BF%9E%E9%80%9A%E6%80%A7%22%5D%0A%20%20DIR%20--%3E%20NLINK%5B%22%E9%93%BE%E6%8E%A5%E8%AE%A1%E6%95%B0%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>fsck 把文件系统从「可能的字节」变成「满足不变量的元数据」。它不能恢复被覆盖的用户数据，只能让树可挂载。日志缩小了必须跑全量的概率；COW 把「半更新树」变成不太该出现的事件，检查器更多是校验与配额审计。不要把 fsck 写成数据库的 <code>CHECK TABLE</code>：没有元组模式，只有块与目录。</p><p>强制 fsck 的策略（周期、错误挂载）是运维旋钮；课序只要求：检查器是布局的对偶程序。</p><p>实现上：e2fsck 的 pass 顺序不能随意调换：先确认位图与 inode 表完好，再谈目录树，否则会把坏指针当合法硬链接。日志文件系统在 clean 标志下跳过，脏挂载则先重放再决定是否全量。 读法上只引用<a href="/cs/soft-updates">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>fsck</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每个 FS 的全部交互式提问项。不保证修完后应用级文件内容正确。下一课从结构一致转到运行时：<code>mmap</code> 与 <code>read</code> 是否看见同一页，页缓存与文件映射如何共帧。</p><p>版本字段会变，课序钉的是机制对象「fsck」，不是某一主线内核的结构体名。 后课默认：盘上结构可由检查器核对。同一文件的映射视图与系统调用视图如何共页，下一课 mmap 一致。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>fsck 按阶段核对位图、inode、目录与计数。</li><li>日志/COW 减少全量修复，不取消检查器。</li><li>mmap 与页缓存一致是下一课。</li><li>出处：McKusick and Kowalski；<em>OSTEP</em>；e2fsprogs 文档。</li></ul>',11))])}const T=t(p,[["render",E]]);export{A as __pageData,T as default};
